      `})]})},Z2=n=>h.jsxs("svg",{xmlns:"http://www.w3.org/2000/svg",viewBox:"0 0 24 24",fill:"currentColor",...n,children:[h.jsx("path",{d:"M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"}),h.jsx("path",{d:"M0 0h24v24H0z",fill:"none"})]}),ke={modules:[{id:"module1",title:Ne.module1Title,time:{[l.EN]:"2 min read",[l.VN]:"2 phút đọc"}},{id:"module2",title:Ne.module2Title,time:{[l.EN]:"3 min practice",[l.VN]:"3 phút thực hành"}},{id:"module3",title:Ne.module3Title,time:{[l.EN]:"3 min toolkit",[l.VN]:"3 phút công cụ"}},{id:"module4",title:Ne.module4Title,time:{[l.EN]:"2 min read",[l.VN]:"2 phút đọc"}}],moduleDetails:{module1:{heading:{[l.EN]:"Understanding autistic communication",[l.VN]:"Hiểu cách giao tiếp của người tự kỷ"},subtitle:{[l.EN]:"Why interviews feel so different for your child.",[l.VN]:"Vì sao phỏng vấn lại khác với con bạn như vậy."},bullets:[{id:"m1-b1",text:{[l.EN]:"Interviews often reward fast talking and eye contact – things that can be draining for autistic people.",[l.VN]:"Phỏng vấn thường đánh giá cao nói nhanh và nhìn thẳng – những điều có thể rất mệt với người tự kỷ."}},{id:"m1-b2",text:{[l.EN]:"Your child may think slowly and deeply. Silence can mean “thinking”, not “stuck”.",[l.VN]:"Con bạn có thể suy nghĩ chậm nhưng sâu. Sự im lặng thường là “đang suy nghĩ”, không phải “bí”."}},{id:"m1-b3",text:{[l.EN]:"Different body language (eye contact, stimming, posture) is often self-regulation, not disrespect.",[l.VN]:"Ngôn ngữ cơ thể khác (ánh mắt, hành vi tự kích thích, tư thế) thường là cách tự điều chỉnh, không phải vô lễ."}}],recap:{[l.EN]:"Goal: see your child’s interview through their eyes, so you can support, not “fix”, who they are.",[l.VN]:"Mục tiêu: nhìn buổi phỏng vấn qua góc nhìn của con, để bạn hỗ trợ chứ không “sửa” con."}},module2:{heading:{[l.EN]:"Practice together in small steps",[l.VN]:"Luyện tập cùng con theo từng bước nhỏ"},subtitle:{[l.EN]:"Short, predictable routines work better than “big talks”.",[l.VN]:"Các thói quen ngắn, dễ đoán hiệu quả hơn “buổi nói chuyện lớn”."},bullets:[{id:"m2-b1",text:{[l.EN]:"Pick one question per day (for example: “Tell me about a project you finished”).",[l.VN]:"Chọn một câu hỏi mỗi ngày (ví dụ: “Kể về một dự án con đã hoàn thành”)."}},{id:"m2-b2",text:{[l.EN]:"Use a timer (2–3 minutes) so your child knows when the practice will end.",[l.VN]:"Dùng đồng hồ bấm giờ (2–3 phút) để con biết khi nào buổi luyện tập kết thúc."}},{id:"m2-b3",text:{[l.EN]:"Let them answer in any format first: typing, writing, drawing, or speaking.",[l.VN]:"Cho con trả lời bằng bất kỳ hình thức nào trước: gõ, viết, vẽ hoặc nói."}}],recap:{[l.EN]:"Short, regular practice builds more confidence than one long, stressful session.",[l.VN]:"Luyện tập ngắn, đều đặn tạo tự tin nhiều hơn là một buổi dài và căng thẳng."}},module3:{heading:{[l.EN]:"Build a pre-interview routine",[l.VN]:"Xây dựng nghi thức trước phỏng vấn"},subtitle:{[l.EN]:"A repeatable checklist helps both you and your child feel calmer.",[l.VN]:"Checklist có thể lặp lại giúp cả bạn và con bình tĩnh hơn."},bullets:[{id:"m3-b1",text:{[l.EN]:"Agree on a simple routine: drink water, quick movement or stretch, one breathing exercise.",[l.VN]:"Thống nhất một nghi thức đơn giản: uống nước, vận động/giãn cơ nhanh, một bài thở ngắn."}},{id:"m3-b2",text:{[l.EN]:"Prepare “comfort items” if helpful: small fidget, written notes, or a structure card with question types.",[l.VN]:"Chuẩn bị “vật an tâm” nếu phù hợp: đồ fidget nhỏ, ghi chú, hoặc thẻ cấu trúc với các loại câu hỏi."}},{id:"m3-b3",text:{[l.EN]:"Decide in advance who speaks during introductions and how to ask for breaks.",[l.VN]:"Quyết định trước ai sẽ nói trong phần giới thiệu và cách xin nghỉ giải lao."}}],recap:{[l.EN]:"Familiar routines lower anxiety. Your child can focus on the questions, not on “what happens next?”.",[l.VN]:"Nghi thức quen thuộc giúp giảm lo âu. Con có thể tập trung vào câu hỏi, không phải “chuyện gì xảy ra tiếp theo?”."}},module4:{heading:{[l.EN]:"Advocating with and for your child",[l.VN]:"Đồng hành và lên tiếng cùng con"},subtitle:{[l.EN]:"Support can be gentle and practical – not confrontational.",[l.VN]:"Sự hỗ trợ có thể nhẹ nhàng và thực tế – không nhất thiết phải đối đầu."},bullets:[{id:"m4-b1",text:{[l.EN]:"Help your child write a short “support note” about what helps them do their best.",[l.VN]:"Giúp con viết một “tờ ghi chú hỗ trợ” về những điều giúp con thể hiện tốt nhất."}},{id:"m4-b2",text:{[l.EN]:"Ask employers about accommodations in a neutral way (extra time, written questions, quiet space).",[l.VN]:"Hỏi nhà tuyển dụng về hỗ trợ hợp lý một cách trung lập (thêm thời gian, câu hỏi bằng văn bản, không gian yên tĩnh)."}},{id:"m4-b3",text:{[l.EN]:"After each interview, debrief gently: “What felt okay?” and “What was hard?”.",[l.VN]:"Sau mỗi buổi phỏng vấn, trao đổi nhẹ nhàng: “Điều gì ổn?” và “Điều gì khó?”."}}],recap:{[l.EN]:"The goal is not a “perfect” interview – it is a safer, more respectful experience for your child.",[l.VN]:"Mục tiêu không phải là buổi phỏng vấn “hoàn hảo” mà là trải nghiệm an toàn, tôn trọng hơn cho con."}}},faqs:[{q:{[l.EN]:"What if my child avoids eye contact?",[l.VN]:"Nếu con tôi tránh giao tiếp bằng mắt thì sao?"},a:{[l.EN]:"It's often a way to focus better on listening. Encourage alternatives like nodding or brief glances. It is not a sign of dishonesty.",[l.VN]:"Đó thường là cách để tập trung lắng nghe tốt hơn. Hãy khuyến khích các cách thay thế như gật đầu hoặc liếc nhìn nhanh. Đó không phải là dấu hiệu của sự không trung thực."}},{q:{[l.EN]:'How to handle "stimming" (self-stimulatory behavior)?',[l.VN]:"Làm thế nào để xử lý hành vi tự kích thích?"},a:{[l.EN]:"Stimming is a natural way to regulate anxiety. As long as it's not harmful, it's best to allow it. A small, quiet fidget tool can be helpful.",[l.VN]:"Hành vi tự kích thích là một cách tự nhiên để điều chỉnh sự lo âu. Miễn là nó không gây hại, tốt nhất là cho phép nó. Một công cụ nhỏ, yên tĩnh có thể hữu ích."}},{q:{[l.EN]:"Should they disclose their autism?",[l.VN]:"Con có nên tiết lộ về chứng tự kỷ của mình không?"},a:{[l.EN]:"This is a personal choice. Practice helps them describe their strengths and needs, whether they choose to disclose or not. Focus on their comfort and context.",[l.VN]:"Đây là một lựa chọn cá nhân. Luyện tập giúp họ mô tả điểm mạnh và nhu cầu của mình, cho dù họ chọn tiết lộ hay không. Hãy tập trung vào sự thoải mái và bối cảnh của họ."}},{q:{[l.EN]:"What if my child has a shutdown or meltdown?",[l.VN]:"Nếu con tôi bị “shutdown” hoặc “meltdown” thì sao?"},a:{[l.EN]:"Plan a simple safety plan in advance: a code word for “I need a break”, a quiet space, and one trusted person they can message or call afterwards.",[l.VN]:"Hãy chuẩn bị sẵn một kế hoạch an toàn đơn giản: một mật mã để nói “con cần nghỉ”, một không gian yên tĩnh và một người đáng tin cậy con có thể nhắn hoặc gọi sau đó."}},{q:{[l.EN]:"How much should I “push” my child to practice?",[l.VN]:"Tôi nên “thúc” con luyện tập đến mức nào?"},a:{[l.EN]:"Use gentle, predictable structure instead of pressure. Agree together on tiny steps (5–10 minutes), and always end with something your child enjoys.",[l.VN]:"Hãy dùng cấu trúc nhẹ nhàng, dễ đoán thay vì ép buộc. Cùng con thống nhất các bước rất nhỏ (5–10 phút) và luôn kết thúc bằng hoạt động con thích."}}],moduleCompletedToast:{[l.EN]:"Nice! Module completed.",[l.VN]:"Tốt lắm! Bạn đã hoàn thành mô-đun này."},resources:[{name:"Vietnam Autism Network (VAN)",desc:{[l.EN]:"A leading network connecting families, professionals, and resources across Vietnam.",[l.VN]:"Một mạng lưới hàng đầu kết nối các gia đình, chuyên gia và tài nguyên trên khắp Việt Nam."},url:"#"},{name:"Saigon Children's Charity",desc:{[l.EN]:"Offers programs that support disadvantaged children, including those with disabilities.",[l.VN]:"Cung cấp các chương trình hỗ trợ trẻ em có hoàn cảnh khó khăn, bao gồm cả trẻ khuyết tật."},url:"#"},{name:"Action to the Community Development Institute (ACDC)",desc:{[l.EN]:"Works to ensure high quality of life for persons with disabilities in Vietnam.",[l.VN]:"Hoạt động để đảm bảo chất lượng cuộc sống cao cho người khuyết tật tại Việt Nam."},url:"#"},{name:"Vietnam's Autism Project (VAP)",desc:{[l.EN]:"Economic model project for autistic people in Vietnam.",[l.VN]:"Dự án mô hình kinh tế cho người tự kỷ Việt Nam."},url:"#"},{name:"Parent support groups (online)",desc:{[l.EN]:"Look for moderated Facebook or Zalo groups where parents share autism-friendly job and training opportunities.",[l.VN]:"Tìm các nhóm Facebook hoặc Zalo có quản trị, nơi phụ huynh chia sẻ cơ hội việc làm và đào tạo thân thiện với người tự kỷ."},url:"#"}],testimonials:[{id:"t1",name:{[l.EN]:"Mrs. Lan",[l.VN]:"Cô Lan"},role:{[l.EN]:"Parent of a 21-year-old",[l.VN]:"Phụ huynh của con 21 tuổi"},quote:{[l.EN]:"After practicing the STAR stories, my son answered with confidence in his internship interview.",[l.VN]:"Sau khi luyện câu chuyện STAR, con tôi trả lời tự tin trong buổi phỏng vấn thực tập."},videoUrl:"",thumbnail:"/Images/video_placeholder.jpg"},{id:"t2",name:{[l.EN]:"Mr. Minh",[l.VN]:"Anh Minh"},role:{[l.EN]:"Father of a 19-year-old",[l.VN]:"Bố của con 19 tuổi"},quote:{[l.EN]:"The pre-interview routine lowered anxiety. We now have a checklist that actually works.",[l.VN]:"Nghi thức trước phỏng vấn giúp giảm lo âu. Giờ chúng tôi có checklist thực sự hiệu quả."},videoUrl:"",thumbnail:""},{id:"t3",name:{[l.EN]:"Ms. Hoa",[l.VN]:"Chị Hoa"},role:{[l.EN]:"Parent & Advocate",[l.VN]:"Phụ huynh & Người vận động"},quote:{[l.EN]:"The guidance was practical and respectful. We finally felt understood.",[l.VN]:"Hướng dẫn thực tế và tôn trọng. Cuối cùng chúng tôi thấy được thấu hiểu."},videoUrl:"",thumbnail:""}],psychologists:[{id:"psy1",name:{[l.EN]:"Dr. Thu Nguyen",[l.VN]:"TS. Nguyễn Thu"},title:{[l.EN]:"Clinical Psychologist (Autism & Anxiety)",[l.VN]:"Nhà tâm lý lâm sàng (Tự kỷ & Lo âu)"},org:{[l.EN]:"City Children’s Hospital",[l.VN]:"BV Nhi Đồng TP.HCM"},location:{[l.EN]:"Ho Chi Minh City",[l.VN]:"TP. Hồ Chí Minh"},languages:["EN","VN"],specialties:["Autism","Anxiety","Parent training"],bio:{[l.EN]:"15+ years supporting autistic teens and families. Focus on interview readiness and social coaching.",[l.VN]:"Hơn 15 năm hỗ trợ thanh thiếu niên tự kỷ và gia đình. Tập trung vào chuẩn bị phỏng vấn và huấn luyện kỹ năng xã hội."},photo:"/Images/psychologists/thu.jpg",contact:{email:"thu.nguyen@example.com",website:"",phone:""},bookingUrl:"",isAvailable:!0},{id:"psy2",name:{[l.EN]:"Ms. Linh Pham",[l.VN]:"Cô Phạm Linh"},title:{[l.EN]:"Educational Psychologist",[l.VN]:"Nhà tâm lý giáo dục"},org:{[l.EN]:"Imago Work",[l.VN]:"Imago Work"},location:{[l.EN]:"Hanoi",[l.VN]:"Hà Nội"},languages:["VN"],specialties:["Vocational skills","Executive functioning"],bio:{[l.EN]:"Supports work readiness and executive skills for young adults.",[l.VN]:"Hỗ trợ sẵn sàng đi làm và kỹ năng điều hành cho thanh niên."},photo:"/Images/psychologists/linh.jpg",contact:{email:"linh.pham@example.com",website:"",phone:""},bookingUrl:"",isAvailable:!1}],ui:{testimonialsTitle:{[l.EN]:"Parent success stories",[l.VN]:"Câu chuyện thành công của phụ huynh"},testimonialsCTA:{[l.EN]:"Watch story",[l.VN]:"Xem câu chuyện"},videoComingSoon:{[l.EN]:"Video coming soon!",[l.VN]:"Video sẽ có sớm!"},psychologistsTitle:{[l.EN]:"Psychologists",[l.VN]:"Chuyên gia tâm lý"},psychologistFilters:{[l.EN]:"Filters",[l.VN]:"Bộ lọc"},searchPlaceholder:{[l.EN]:"Search name, specialty, or location…",[l.VN]:"Tìm tên, chuyên môn hoặc địa điểm…"},onlyAvailable:{[l.EN]:"Only available",[l.VN]:"Chỉ hiển thị còn trống"},contact:{[l.EN]:"Contact",[l.VN]:"Liên hệ"},viewProfile:{[l.EN]:"View profile",[l.VN]:"Xem hồ sơ"},book:{[l.EN]:"Book",[l.VN]:"Đặt lịch"},parentIntroTitle:{[l.EN]:"You know your child best",[l.VN]:"Bạn là người hiểu con mình nhất"},parentIntroBody:{[l.EN]:"This space gives you short, autism-affirming tools to support your child before, during, and after interviews.",[l.VN]:"Phần này cung cấp các công cụ ngắn gọn, tôn trọng tự kỷ để bạn hỗ trợ con trước, trong và sau buổi phỏng vấn."}},practiceWithChild:{[l.EN]:"Practice with your child",[l.VN]:"Luyện tập cùng con"},jobseekerCoachLine:{[l.EN]:"Open the Jobseeker coach to role-play interview answers together.",[l.VN]:"Mở công cụ Người tìm việc để luyện trả lời phỏng vấn cùng nhau."},allLessonsDone:{[l.EN]:"Great work! You finished all lessons.",[l.VN]:"Tuyệt lắm! Bạn đã hoàn thành tất cả bài học."},readyToPracticeQ:{[l.EN]:"Ready to practice together? Jump into the Jobseeker coach.",[l.VN]:"Sẵn sàng luyện tập cùng nhau? Hãy mở công cụ Người tìm việc."}},e_=({title:n,time:e,isCompleted:o,onClick:a})=>h.jsx("button",{type:"button",onClick:a,className:`
